(23311,0,1,'AYAYA! One day me have dat booterang...',12,0,100,0,0,0,'Disobedient Dragonmaw Peon'),
(23311,0,2,'HEY! No more booterang! Me sorry! Me work!',12,0,100,0,0,0,'Disobedient Dragonmaw Peon'),
(23311,0,3,'OOF! Booterang hurted me! Me tink work better den booterang!',12,0,100,0,0,0,'Disobedient Dragonmaw Peon'),
(23311,0,4,'OWWWW! Ok, ok, me go back to work!',12,0,100,0,0,0,'Disobedient Dragonmaw Peon'),
(23311,0,5,'WHY IT PUT DA BOOTERANG ON DA SKIN?? WHY??',12,0,100,0,0,0,'Disobedient Dragonmaw Peon'),
(23311,0,6,'You is bad orc... baaad... or... argh!',12,0,100,0,0,0,'Disobedient Dragonmaw Peon'),
(23311,0,7,'Hey... me not feel so good.',12,0,100,0,0,0,'Disobedient Dragonmaw Peon - On Script Action');
