-- Shadowmoon Valley: the credit scripts of A Necessary Distraction, Blast the Infernals! and The Booterang (with the
-- peons and work nodes missing from the 3.3.5 layout, both databases agree).

-- A Necessary Distraction
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (21506);
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (21506) AND `AIName` = '' AND `ScriptName` = '';

-- Blast the Infernals!
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (21512);
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (21512) AND `AIName` = '' AND `ScriptName` = '';

-- The Booterang: A Cure For The Common Worthless Peon
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (23308,23311);
DELETE FROM `creature_text` WHERE `entry` IN (23311);
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (23308,23311) AND `AIName` = '' AND `ScriptName` = '';

